def _proof_kompile_commands(workspace: Path) -> tuple[KompileCommand, ...]:
    prove = workspace / "prove.sh"
    if not prove.is_file() or prove.is_symlink():
        return ()
    logical_lines = prove.read_text().replace("\\\n", " ").splitlines()
